''basedon'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM filtered_hiproinst) ), address_cte AS ( SELECT proc_inst_id_, text_ AS address FROM camunda.act_hi_varinst WHERE name_ = ''address'' AND var_type_ = ''string'' AND proc_inst_id_ IN (SELECT proc_inst_id_ FROM basedon_cte) ) SELECT CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN CASE WHEN closedby.assignee_ IS NOT NULL THEN wuser.vcemailid ELSE ''Auto Closed'' END ELSE NULL END AS \"Closed By\", hiproinst.end_time_ AS \"Closed Date\", CASE WHEN hiproinst.state_ = ''ACTIVE'' THEN task.name_ ELSE ''Closed'' END AS \"Stage\", wu.vcemailid AS \"Claimed By\", hiproinst.start_time_ AS \"Created Date\", CASE WHEN hiproinst.state_ != ''ACTIVE'' THEN ''Closed'' WHEN task.assignee_ IS NOT NULL THEN ''Claimed'' ELSE ''Unclaimed'' END AS \"Status\", pdef.name_ AS \"Case Type\", CASE WHEN task.assignee_ IS NOT NULL THEN oplog.time_ ELSE NULL END AS \"Claimed On\", payer_cte.payer AS \"Payer\", payee_cte.payee AS \"Payee\", transaction_amount_cte.amount AS \"Amount\", ticket_id_cte.case_id AS \"Case ID\", alert_cte.alert AS \"Alert\", basedon_cte.basedon AS \"Alert Type\" , address_cte.address AS \"Address\" FROM filtered_hiproinst hiproinst JOIN camunda.act_re_procdef pdef ON pdef.id_ = hiproinst.proc_def_id_ LEFT JOIN ranked_closedby closedby ON closedby.proc_inst_id_ = hiproinst.proc_inst_id_ AND closedby.rn = 1 LEFT JOIN camunda.act_ru_task task ON task.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ui.webuser wu ON wu.iuserid = CAST(task.assignee_ AS INTEGER) LEFT JOIN ranked_oplog oplog ON oplog.proc_inst_id_ = task.proc_inst_id_ AND oplog.rn = 1 LEFT JOIN ui.webuser wuser ON wuser.iuserid = CAST(closedby.assignee_ AS INTEGER) LEFT JOIN payer_cte ON payer_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN payee_cte ON payee_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN transaction_amount_cte ON transaction_amount_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN ticket_id_cte ON ticket_id_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN alert_cte ON alert_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN address_cte ON address_cte.proc_inst_id_ = hiproinst.proc_inst_id_ LEFT JOIN basedon_cte ON basedon_cte.proc_inst_id_ = hiproinst.proc_inst_id_ ;",
